  const SUNDAY = (k, t) => k === 32 ? 'Zacchaeus Sunday (32nd Sunday after Pentecost)' : k === 1 ? 'Sunday of All Saints (1st Sunday after Pentecost)' : ord(k) + ' Sunday after Pentecost';
  function title(e, dow, label) { return /^(Monday|Tuesday|Wednesday|Thursday|Friday|Saturday)$/.test(e.t) && label ? `${e.t} ${label}` : e.t; }
